/* Strict Source-owned CheckInterlude -> TurnEnd state/RNG/queued effect replay. */
#define main gas_replay_main
#include "gas-lifecycle-test.c"
#undef main
static void small(const pr_battle *bt,const pr_pokemon *p,const pr_pokemon *enemy,double *v){v[0]=bt->turn;v[1]=p->hp;v[2]=p->temp_turn_count;v[3]=p->temp_wave_turn_count;v[4]=enemy->temp_turn_count;v[5]=enemy->temp_wave_turn_count;v[6]=bt->weather;v[7]=bt->weather_turns_left;v[8]=bt->terrain;v[9]=bt->terrain_turns_left;v[10]=bt->n_arena_tags;v[11]=bt->n_arena_tags?bt->arena_tags[0].turn_count:0;}
static void texthex(const pr_msg *m,char *out,size_t cap){pr_text_source src={locale_get,NULL,"en"};char s[1024];size_t n=pr_msg_format(m,&src,s,sizeof s);if(n>=sizeof s||n*2+1>cap)bad();if(!n){strcpy(out,"-");return;}for(size_t i=0;i<n;i++)snprintf(out+i*2,3,"%02x",(unsigned char)s[i]);}
int main(int argc,char **argv){
 if(argc!=2)return 2;input=fopen(argv[1],"r");if(!input||!getenv("TURNTEST_LOCALES"))return 2;pr_closures_init();double h[3];read_vector("INTERLUDEEND ",h,3);if(h[0]!=1)bad();int n=integer(h[1],512,100000),fail=0;
 for(int i=0;i<n;i++){
  static pr_battle bt;static pr_engine e;memset(&bt,0,sizeof bt);memset(&e,0,sizeof e);bt.engine=&e;e.n_levels=1;e.current=-1;bt.ignoring_effect_source=-1;bt.last_used_pokeball=-1;
  double c[6],s[14],v[12];read_vector("C ",c,6);if(c[0]!=i)bad();bt.wave_index=integer(c[1],1,1000000);int alive=integer(c[2],0,1);bt.weather=integer(c[3],0,WEATHER_TYPE_FOG);bt.terrain=integer(c[4],0,TERRAIN_PSYCHIC);int duration=integer(c[5],1,3);bt.weather_turns_left=bt.weather_max_duration=bt.weather?duration:0;bt.terrain_turns_left=bt.terrain_max_duration=bt.terrain?duration:0;
  char *seed=line_read("W ");seed[strcspn(seed,"\n")]=0;if(!*seed||strlen(seed)>64||strchr(seed,' '))bad();pr_seed_from_ascii(&bt.wave_seed,seed);
  read_vector("S ",s,14);pr_pokemon mons[2]={0};for(int k=0;k<2;k++){pr_pokemon *p=&mons[k];if(s[k]<0||s[k]>UINT32_MAX||floor(s[k])!=s[k])bad();p->id=(uint32_t)s[k];p->species=k?SPECIES_ID_MAGIKARP:SPECIES_ID_BULBASAUR;p->is_player=!k;p->on_field=true;p->ability=p->base_ability=ABILITY_ID_BALL_FETCH;p->ability_override=-1;for(int j=0;j<6;j++)p->stats[j]=integer(s[2+k*6+j],1,100000);bt.field[k*2]=bt.party[k][0]=p;bt.n_party[k]=1;}
  read_vector("I ",v,12);bt.turn=integer(v[0],1,1000);mons[0].hp=integer(v[1],1,mons[0].stats[0]);mons[1].hp=alive?mons[1].stats[0]:0;mons[0].temp_turn_count=integer(v[2],0,100);mons[0].temp_wave_turn_count=integer(v[3],0,100);mons[1].temp_turn_count=integer(v[4],0,100);mons[1].temp_wave_turn_count=integer(v[5],0,100);bt.n_arena_tags=1;bt.arena_tags[0]=(pr_arena_tag){.type=ARENA_TAG_TYPE_MIST,.side=ARENA_TAG_SIDE_BOTH,.turn_count=duration,.max_duration=duration,.source_move=MOVE_ID_MIST,.source_id=-1,.layers=1};
  double initial[12];small(&bt,&mons[0],&mons[1],initial);if(memcmp(initial,v,sizeof v))bad();rng_read("R ",&bt.rng);rng_read("B ",&bt.battle_rng);bt.rng_live=bt.battle_rng_live=true;
  const pr_phase_type types[]={PH_WEATHER_EFFECT,PH_BERRY,PH_CHECK_STATUS_EFFECT,PH_POSITIONAL_TAG,PH_TURN_END};int end=-1;for(int k=0;k<5;k++){int ph=pr_phase_new(&e,types[k],k?-1:0);e.levels[0][e.level_len[0]++]=ph;if(k==4)end=ph;}
  int check=pr_phase_new(&e,PH_CHECK_INTERLUDE,-1);e.current=check;pr_phase_run(&bt,&e,check);double a[1];read_vector("A ",a,1);bool exact=integer(a[0],0,1)==e.pool[end].upcoming_interlude;if(!pr_phase_try_remove(&bt,&e,PH_TURN_END,-1))bad();e.current=end;pr_phase_run(&bt,&e,end);
  read_vector("O ",v,12);for(int k=0;k<12;k++)integer(v[k],0,1000000);double actual[12];small(&bt,&mons[0],&mons[1],actual);if(memcmp(actual,v,sizeof v)){exact=false;if(fail<12){fprintf(stderr,"end%d state ",i);for(int k=0;k<12;k++)fprintf(stderr,"%g/%g ",actual[k],v[k]);fputc('\n',stderr);}}
  double q[1];read_vector("Q ",q,1);int count=integer(q[0],0,128),seen=0;
  for(int l=0;l<e.n_levels;l++)for(int k=0;k<e.level_len[l];k++){
   if(seen++>=count){exact=false;continue;}char *row=line_read("P "),name[64],hex[2048],extra;int battler;double hp;if(sscanf(row,"%63s %d %lf %2047s %c",name,&battler,&hp,hex,&extra)!=4||!isfinite(hp)||hp<0||battler<-1||battler>3)bad();if(strcmp(hex,"-")&&(strlen(hex)%2||strspn(hex,"0123456789abcdef")!=strlen(hex)))bad();pr_phase *ph=&e.pool[e.levels[l][k]];char got[2048]="-";if(ph->type==PH_MESSAGE||ph->type==PH_POKEMON_HEAL)texthex(&ph->msg,got,sizeof got);double heal=ph->type==PH_POKEMON_HEAL?ph->heal_hp:0;
   if(strcmp(name,pr_phase_name[ph->type])||battler!=ph->battler||hp!=heal||strcmp(hex,got)){if(fail<12)fprintf(stderr,"end%d queue expected%s/%d/%g/%s got%s/%d/%g/%s\n",i,name,battler,hp,hex,pr_phase_name[ph->type],ph->battler,heal,got);exact=false;}
  }
  while(seen<count){line_read("P ");seen++;exact=false;}pr_rng rng;rng_read("RO ",&rng);exact&=rng_equal(rng,bt.rng);char *bo=line_read("BO ");if(!strcmp(bo,"-\n"))exact&=!bt.battle_rng_live;else{double r[4];char extra;if(sscanf(bo,"%lf %lf %lf %lf %c",r,r+1,r+2,r+3,&extra)!=4)bad();integer(r[0],0,INT32_MAX);for(int k=1;k<4;k++)if(!isfinite(r[k])||r[k]<0||r[k]>=1)bad();rng=(pr_rng){.c=(uint32_t)r[0],.s0=r[1],.s1=r[2],.s2=r[3]};exact&=bt.battle_rng_live&&rng_equal(rng,bt.battle_rng);}if(strcmp(line_read("E"),"\n"))bad();exact&=!bt.n_unported&&!e.overflow;if(!exact){if(fail<12)fprintf(stderr,"interlude-end case%d wave%d unported%d\n",i,bt.wave_index,bt.n_unported);if(fail<12)for(int z=0;z<bt.n_unported;z++)fprintf(stderr,"feature %s\n",pr_unported_name(bt.unported[z]));fail++;}
 }
 double footer[1];read_vector("INTERLUDEEND_COMPLETE ",footer,1);if(footer[0]!=n||fgetc(input)!=EOF)bad();printf("Interlude end: %d complete, %d failures\n",n,fail);return fail?1:0;
}
